PREFIX : <https://w3id.org/rastro/energia#>
SELECT (SUM(?oilC * ?pct / 100) AS ?total) WHERE {
  {
    SELECT ?c (SUM(?oil) AS ?oilC) WHERE {
      ?p a :WellProduction ; :concession ?c ; :oil ?oil .
    } GROUP BY ?c
  }
  {
    SELECT DISTINCT ?s ?c ?pct WHERE {
      ?s a :Stake ; :concession ?c ; :partner ?co ; :percent ?pct .
      ?co :name ?n .
      FILTER(REGEX(?n, "^YPF( S\\.?A\\.?)?$", "i"))
    }
  }
}
